!function(){var e=document.getElementById("contactForm"),t=document.getElementById("msgSubmit");e.addEventListener("submit",function(n){if(n.preventDefault(),e.reportValidity()){var o=document.getElementById("fname").value,s=document.getElementById("lname").value,m=document.getElementById("phone").value,a=document.getElementById("email").value,i=document.getElementById("message").value;fetch("https://saint-roman-main.onrender.com/api/public/support-tickets",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:o+" "+s,email:a,phone:m,subject:"Contact form submission",message:i||"(no message provided)"})}).then(function(e){return e.json().then(function(t){if(!e.ok)throw new Error(t.error||"Could not send message");return t})}).then(function(){t.textContent="Thanks — we received your message and will get back to you soon.",t.classList.remove("hidden"),e.reset()}).catch(function(e){t.textContent=e.message,t.style.color="#c0392b",t.classList.remove("hidden")})}})}();